  preparing_artwork: "Preparing artwork",
  generating_production_geometry: "Generating production geometry",
  validating_production_project: "Validating production project",
  ready_for_orca: "Ready for Snapmaker Orca",
  transferring_to_companion: "Transferring to Windows companion",
