async function renderPilotApplications(){const root=$("pilot-applications");root.replaceChildren();try{const {data}=await api("/api/pilot-applications");if(!data.applications?.length){root.append(textNode("p","No pilot applications yet.","muted"));return}for(const app of data.applications){const card=document.createElement("article");card.className="wholesale-card";card.append(textNode("strong",app.businessName));card.append(textNode("p",`${app.contactName} · ${app.email}${app.phone?` · ${app.phone}`:""}`));card.append(textNode("p",`${pretty(app.status)} · received ${new Date(app.createdAt).toLocaleString()}`));card.append(textNode("p",`${app.businessType} · estimated monthly demand: ${app.monthlyDemand}`,"muted"));const sampleStyle=app.sampleStyle==="billboard"?"Billboard":app.sampleStyle==="standard"?"Standard":"Not recorded (legacy application)";card.append(textNode("p",`Sample set: 6 complimentary blank sleeves, one size 0-5, ${sampleStyle} style`,"muted"));card.append(textNode("p","Samples are for fit testing, material evaluation, and product demonstrations.","muted"));card.append(textNode("p",app.intendedUse));if(app.comments)card.append(textNode("p",`Additional notes: ${app.comments}`,"muted"));const row=document.createElement("div");row.className="row";if(app.status==="pending"){const approve=document.createElement("button");approve.type="button";approve.textContent="Approve and issue access";approve.addEventListener("click",()=>reviewPilotApplication(app.id,"approve"));const decline=document.createElement("button");decline.type="button";decline.className="danger";decline.textContent="Decline";decline.addEventListener("click",()=>reviewPilotApplication(app.id,"decline"));row.append(approve,decline)}else if(app.status==="approved"&&(!app.wholesalePartnerId||app.partnerAccessStatus==="revoked")){const issue=document.createElement("button");issue.type="button";issue.textContent=app.partnerAccessStatus==="revoked"?"Issue replacement credential":"Issue partner access";issue.addEventListener("click",()=>reviewPilotApplication(app.id,"issue_access"));row.append(issue)}else if(app.wholesalePartnerId){const state=document.createElement("span");state.className="pill";state.textContent=`Wholesale access: ${app.partnerAccessStatus}`;row.append(state);if(app.partnerAccessStatus!=="revoked"){const toggle=document.createElement("button");toggle.type="button";toggle.className=app.partnerAccessStatus==="active"?"danger":"secondary";toggle.textContent=app.partnerAccessStatus==="active"?"Suspend access":"Reactivate access";toggle.addEventListener("click",()=>updateWholesalePartnerAccess(app.wholesalePartnerId,app.partnerAccessStatus==="active"?"suspended":"active"));const revoke=document.createElement("button");revoke.type="button";revoke.className="danger";revoke.textContent="Revoke permanently";revoke.addEventListener("click",()=>updateWholesalePartnerAccess(app.wholesalePartnerId,"revoked"));row.append(toggle,revoke)}}card.append(row);root.append(card)}}catch(error){root.append(textNode("p",error.message,"error"))}}
